mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  float y = p.y * 1.4 + time * 1.8;
  vec3 h1 = p - vec3(cos(y) * 0.85, p.y, sin(y) * 0.85);
  vec3 h2 = p - vec3(cos(y + 3.1415) * 0.85, p.y, sin(y + 3.1415) * 0.85);
  float d1 = length(h1.xz) - 0.22;
  float d2 = length(h2.xz) - 0.22;
  return min(d1, d2);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.5);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.03, 0.06);
  if (t < 8.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(map(pos+e.xyy)-map(pos-e.xyy), map(pos+e.yxy)-map(pos-e.yxy), map(pos+e.yyx)-map(pos-e.yyx)));
    vec3 l = normalize(vec3(1.0, 2.0, -2.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 64.0);
    float sparkle = pow(max(sin(pos.y * 12.0 + time * 5.0), 0.0), 16.0);
    col = vec3(0.1, 0.15, 0.25) + diff * vec3(0.3, 0.7, 1.0) + (spec + sparkle * 2.5) * vec3(1.0, 1.0, 1.0);
  }
  col += glow * vec3(0.4, 0.8, 1.2) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
